import {
  useState,
  useEffect,
  useRef,
  useMemo,
  Fragment,
  type ReactNode,
} from 'react';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/shared/ui/popover';
import { printHTML } from '@/shared/lib/print';
import {
  Edit2,
  Save,
  X,
  Trash2,
  Upload,
  Image as ImageIcon,
  Search,
  Printer,
  BarChart3,
  ChevronDown,
  User,
  ArrowLeft,
  Sun,
  Moon,
  LogOut,
  Filter,
  ChevronLeft,
  ChevronRight,
  Layers,
  Eye,
  EyeOff,
  Leaf,
  History,
  Archive,
  RotateCcw,
  Clock,
  Minus,
  ScanBarcode,
  Tag,
  Table2,
  Info,
} from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Textarea } from '@/shared/ui/textarea';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/card';
import { Badge } from '@/shared/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/shared/ui/accordion';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/shared/hooks/use-toast';
import { useStoreFilter } from '@/shared/hooks/useStoreData';
import { useAuth } from '@/shared/hooks/useAuth';
import { BatchList } from '@/shared/ui/BatchList';
import { EmbalagemList } from '@/features/produtos/ui/EmbalagemList';
import { PermissionBlur } from '@/shared/ui/PermissionBlur';
import { usePermissions } from '@/shared/hooks/usePermissions';
import { useTheme } from 'next-themes';
import { useNavigate } from 'react-router-dom';
import { useIsMobile } from '@/shared/hooks/use-mobile';
import { useStore } from '@/shared/contexts/StoreContext';
import { StoreSelector } from '@/shared/ui/DashboardStoreSelector';
import { cn } from '@/shared/lib/utils';
import { Avatar, AvatarFallback } from '@/shared/ui/avatar';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
} from '@/shared/ui/dialog';
import { Loader2 } from 'lucide-react';
import { ProductVisibilityMatrix } from '@/features/produtos/ui/ProductVisibilityMatrix';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/shared/ui/tabs';
import { useSetores } from '../model/useSetores';
import { ScannerContent } from '@/features/estoque';
import { LabelPrintingContent } from '@/features/etiquetas';
import { useSearchTelemetry } from '@/shared/lib/telemetry/useSearchTelemetry';
import { withTrace } from '@/shared/lib/telemetry/tracer';
import { wideInfo, wideError } from '@/shared/lib/telemetry/wide-events';
import { handleError } from '@/shared/lib/error-handler';
import {
  recordOperation,
  recordOperationDuration,
  recordError,
} from '@/shared/lib/telemetry/metrics';
import { useTelemetryAttrs } from '@/shared/lib/telemetry/useTelemetryAttrs';

interface Categoria {
  id: number;
  nome: string;
  emoji: string;
  descricao?: string;
}

interface Produto {
  id: number;
  nome: string;
  descricao?: string;
  categoria_id?: number;
  preco_custo?: number;
  codigo_interno?: number;
  unidade_medida: string;
  ativo: boolean;
  setor: string;
  foto_url?: string;
  dias_validade?: number;
}

interface Batch {
  id: string;
  lote_id: string;
  lote: string;
  validade: string;
  fabricacao?: string;
  quantidade: number;
}

interface ProdutoComCategoria extends Produto {
  categoria?: Categoria;
  quantidade_atual?: number;
  quantidade_minima?: number;
  quantidade_maxima?: number;
  oculto?: boolean;
}

const setorEmoji = (nome: string): string => {
  const n = (nome || '').toLowerCase();
  if (n.includes('câmara fria') || n.includes('camara fria')) return '❄️';
  if (n === 'insumos' || n.includes('estoque insumos')) return '🥄';
  if (n === 'mercearia') return '🛒';
  if (n === 'embalagens') return '📦';
  if (n === 'limpeza') return '🧼';
  if (n === 'natal') return '🎅';
  if (n === 'limpeza') return '🧼';
  if (n === 'natal') return '🎅';
  if (n === 'todos') return '🌎';
  return '🏷️';
};

const normalizeSetorForDb = (setor: string): string => {
  const s = (setor || '').trim().toLowerCase();
  if (s === 'estoque insumos') return 'Insumos';
  return setor;
};

// Interface para o relatório
interface ItemRelatorio {
  id: number;
  nome: string;
  unidade: string;
  quantidade_sistema: number;
  categoria: string;
  setor: string;
  codigo_interno?: number;
}

/**
 * Explicação clicável (funciona em toque/mobile, diferente do tooltip nativo):
 * envolve o elemento num popover que abre ao clicar/tocar.
 */
const ExplicacaoEstoque = ({
  texto,
  children,
}: {
  texto: string;
  children: ReactNode;
}) => (
  <Popover>
    <PopoverTrigger asChild>
      <button
        type="button"
        data-mia-skip
        className="inline-flex items-center gap-1 cursor-pointer bg-transparent border-0 p-0 text-inherit font-inherit text-left"
      >
        {children}
        <Info className="h-3 w-3 opacity-50 shrink-0" />
      </button>
    </PopoverTrigger>
    <PopoverContent
      side="top"
      className="max-w-[280px] rounded-xl border-[#57715B]/20 text-xs leading-relaxed text-foreground"
    >
      {texto}
    </PopoverContent>
  </Popover>
);

const Produtos = () => {
  const { hasData, storeId } = useStoreFilter();
  const { user, userProfile, signOut } = useAuth();
  const { hasPermission, canViewEstoque, isAdmin } = usePermissions();
  const { atualizarProdutoSetorUnidade, setores: setoresGestao } = useSetores();
  const hasAccess =
    hasPermission('view_produtos') || canViewEstoque() || isAdmin();
  const { theme, setTheme } = useTheme();
  const navigate = useNavigate();
  const isMobile = useIsMobile();
  const { selectedStore } = useStore();
  const telemetryAttrs = useTelemetryAttrs();
  const [serverVersion, setServerVersion] = useState<string | null>(null);

  useEffect(() => {
    if (isMobile) {
      fetch(`/version.json?t=${Date.now()}`)
        .then((res) => {
          const ct = res.headers.get('content-type') || '';
          if (!res.ok || !ct.includes('application/json')) return null;
          return res.json();
        })
        .then((data) => data && setServerVersion(data.version))
        .catch((err) => handleError(err, { domain: 'produtos', operation: 'fetchServerVersion', showToast: false }));
    }
  }, [isMobile]);
  const [produtos, setProdutos] = useState<ProdutoComCategoria[]>([]);
  const [setores, setSetores] = useState<string[]>([]);
  const [setorSelecionado, setSetorSelecionado] =
    useState<string>('Câmara Fria');
  const [editingProduct, setEditingProduct] = useState<number | null>(null);
  const [modoContagem, setModoContagem] = useState<boolean>(true);
  // Modo consulta: tabela só-leitura pra ver estoque sem mexer na tela de quem opera
  const [modoConsulta, setModoConsulta] = useState<boolean>(false);
  // Janela do mínimo de HOJE — espelha o motor recalcular_minmax_estoque
  // (viagens seg/qua/sex, entrega de manhã; o mínimo cobre a venda até a próxima viagem)
  const infoMinimoHoje = useMemo(() => {
    const nomes = [
      'domingo',
      'segunda',
      'terça',
      'quarta',
      'quinta',
      'sexta',
      'sábado',
    ];
    const janelas: Record<number, { cobre: string; proxima: number }> = {
      1: { cobre: 'seg + ter', proxima: 3 },
      2: { cobre: 'ter', proxima: 3 },
      3: { cobre: 'qua + qui', proxima: 5 },
      4: { cobre: 'qui', proxima: 5 },
      5: { cobre: 'sex + sáb + dom', proxima: 1 },
      6: { cobre: 'sáb + dom', proxima: 1 },
      0: { cobre: 'dom', proxima: 1 },
    };
    const dow = new Date().getDay();
    const janela = janelas[dow];
    return {
      hoje: nomes[dow],
      cobre: janela.cobre,
      proximaViagem: nomes[janela.proxima],
    };
  }, []);

  // Gerenciar mode é admin-only: força Contagem para não-admins
  useEffect(() => {
    if (!modoContagem && !isAdmin()) {
      setModoContagem(true);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [modoContagem]);
  const [collapsedCategories, setCollapsedCategories] = useState<
    Record<number, boolean>
  >({});
  const [batches, setBatches] = useState<Record<number, Batch[]>>({}); // produto_id -> batches
  const [expandedBatches, setExpandedBatches] = useState<
    Record<number, boolean>
  >({});
  const [activeTab, setActiveTab] = useState('products');

  const toggleBatches = (id: number) => {
    setExpandedBatches((prev) => ({ ...prev, [id]: !prev[id] }));
  };

  const toggleCategoryCollapsed = (id: number) => {
    setCollapsedCategories((prev) => ({ ...prev, [id]: !prev[id] }));
  };

  const [newProduct, setNewProduct] = useState<Partial<Produto>>({
    nome: '',
    descricao: '',
    unidade_medida: 'unidade',
    preco_custo: 0,
    ativo: true,
    setor: 'Câmara Fria',
  });
  const [showNewProduct, setShowNewProduct] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [showHidden, setShowHidden] = useState(false);
  const [showArchived, setShowArchived] = useState(false);
  const [showHistoryModal, setShowHistoryModal] = useState<number | null>(null);
  const [productHistory, setProductHistory] = useState<any[]>([]);
  const [loadingHistory, setLoadingHistory] = useState(false);
  const [uploadingImage, setUploadingImage] = useState<number | null>(null);
  const [showPrintDialog, setShowPrintDialog] = useState(false);
  const [isGeneratingReport, setIsGeneratingReport] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const { toast } = useToast();

  const editSessionsRef = useRef<
    Record<
      string,
      {
        startTotal: number;
        lastTotal: number;
        startBatch?: number;
        lastBatch?: number;
      }
    >
  >({});
  const timersRef = useRef<Record<string, number>>({});
  const [pendingConfirm, setPendingConfirm] = useState<Record<string, boolean>>(
    {},
  );
  const debounceMs = 500;

  const commitChange = async (key: string) => {
    const sess = editSessionsRef.current[key];
    if (!sess) return;

    // Snapshot the values we are about to save
    const valueToSave = sess.lastTotal;
    const startValue = sess.startTotal;
    const batchValueToSave = sess.lastBatch;

    const delta = (valueToSave || 0) - (startValue || 0);
    if (!delta) {
      delete editSessionsRef.current[key];
      return;
    }

    const [prodIdStr, estoqueLoteId] = key.split('_');
    const produtoId = parseInt(prodIdStr);

    try {
      if (estoqueLoteId) {
        // Caminho de CAIXA: o ajuste vai por uma RPC atômica. Nada de UPDATE
        // direto em estoque_lotes (que disparava o reconciliador 'sync_lote_auto'
        // fantasma) nem inserção manual de movimentação. A RPC resolve lote
        // vivo/NULL e os triggers sincronizam estoque + estoque_lotes coerentes.
        // "Baixar caixa" = delta negativo do tamanho da caixa → ela some (qtd 0).
        let loteUuid: string | null =
          batches[produtoId]?.find((b) => b.id === estoqueLoteId)?.lote_id ||
          null;

        if (!loteUuid) {
          const { data: loteRow, error: loteRowError } = await supabase
            .from('estoque_lotes')
            .select('lote_id')
            .eq('id', estoqueLoteId)
            .maybeSingle();

          if (loteRowError) throw loteRowError;
          loteUuid = (loteRow as any)?.lote_id || null;
        }

        const { data: rpcData, error: rpcError } = await (supabase.rpc as any)(
          'ajustar_lote_contagem',
          {
            p_lote_id: loteUuid,
            p_produto_master_id: produtoId,
            p_loja_id: storeId,
            p_delta: delta,
            p_motivo: 'contagem_caixa',
            p_observacoes: 'Contagem de caixa',
          },
        );
        if (rpcError) throw rpcError;
        if (rpcData && (rpcData as any).ok === false) {
          throw new Error((rpcData as any).erro || 'Falha ao ajustar caixa');
        }
      } else {
        // Caminho AVULSO / loja sem lote: ajusta o agregado via movimentação de
        // contagem (sem lote). O trigger atualizar_estoque_e_alertas faz o upsert
        // de estoque com quantidade_nova.
        const { data: rpcId } = await supabase.rpc('get_usuario_id_from_auth', {
          user_uuid: user?.id,
        });
        const usuarioIdData = (rpcId as number) || null;
        const tipo = delta > 0 ? 'entrada' : 'saida';
        const quantidadeAbs = Math.abs(delta);

        const { error: movError } = await supabase.from('movimentacoes').insert({
          produto_master_id: produtoId,
          tipo_movimentacao: tipo,
          quantidade: quantidadeAbs,
          quantidade_anterior: startValue,
          quantidade_nova: valueToSave,
          usuario_id: usuarioIdData,
          observacoes: null,
          motivo: 'contagem',
          data_movimentacao: new Date().toISOString(),
          loja_id: storeId,
          lote_id: null,
        });
        if (movError) throw movError;
      }

      // Success! Now handle session cleanup safely
      // Check if the session was updated while we were saving
      if (editSessionsRef.current[key]) {
        if (editSessionsRef.current[key].lastTotal !== valueToSave) {
          // User updated the value again during save.
          // Update the startTotal to be what we just saved, so the next commit
          // (which is already scheduled) calculates the delta correctly from this point.
          editSessionsRef.current[key].startTotal = valueToSave;
          if (typeof batchValueToSave === 'number') {
            editSessionsRef.current[key].startBatch = batchValueToSave;
          }
        } else {
          // No changes since we started saving. Safe to delete.
          delete editSessionsRef.current[key];
        }
      }
    } catch (e) {
      handleError(e, { domain: 'produtos', operation: 'saveCount', showToast: false });
      toast({
        title: 'Erro ao salvar contagem (Tente novamente)',
        variant: 'destructive',
      });
      // CRITICAL: Do NOT delete the session on error.
      // This allows the next user interaction to retry sending the FULL accumulated delta.
      // If we deleted it, the local state would be ahead of DB, and future deltas would be calculated
      // from the wrong baseline, causing permanent data loss.
      // delete editSessionsRef.current[key];
    }
  };

  const scheduleCommit = (key: string, delay = debounceMs) => {
    if (timersRef.current[key]) {
      clearTimeout(timersRef.current[key]);
    }
    timersRef.current[key] = window.setTimeout(async () => {
      await commitChange(key);
      setPendingConfirm((prev) => ({ ...prev, [key]: false }));
      delete timersRef.current[key];
    }, delay);
  };

  const confirmChange = async (produtoId: number) => {
    const key = String(produtoId);
    await commitChange(key);
    setPendingConfirm((prev) => ({ ...prev, [key]: false }));
  };

  const cancelChange = (produtoId: number) => {
    const key = String(produtoId);
    const sess = editSessionsRef.current[key];
    if (sess) {
      setProdutos((prev) =>
        prev.map((p) =>
          p.id === produtoId ? { ...p, quantidade_atual: sess.startTotal } : p,
        ),
      );
      delete editSessionsRef.current[key];
    }
    if (timersRef.current[key]) {
      clearTimeout(timersRef.current[key]);
      delete timersRef.current[key];
    }
    setPendingConfirm((prev) => ({ ...prev, [key]: false }));
  };

  useEffect(() => {
    fetchSetores();
  }, [hasData]);

  useEffect(() => {
    // Ajustar seleção padrão quando setores carregarem
    if (setores.length > 0 && !setores.includes(setorSelecionado)) {
      setSetorSelecionado('Todos');
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [setores]);

  useEffect(() => {
    fetchProdutos();
    fetchBatches(); // Load batches
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [setorSelecionado, hasData, storeId]);

  const fetchBatches = async () => {
    if (!storeId || !hasData) return;
    try {
      const { data, error } = await supabase
        .from('estoque_lotes')
        .select(
          `
          id,
          produto_id,
          lote_id,
          quantidade,
          lotes (
            codigo,
            data_validade,
            data_fabricacao
          )
        `,
        )
        .eq('loja_id', storeId);

      if (error) throw error;

      const batchesByProduct: Record<number, Batch[]> = {};
      (data || []).forEach((item: any) => {
        const prodId = item.produto_id;
        if (!prodId) return;
        // Caixa vazia (qtd 0) não aparece na contagem — só caixas com saldo.
        if (Number(item.quantidade) <= 0) return;

        if (!batchesByProduct[prodId]) batchesByProduct[prodId] = [];
        batchesByProduct[prodId].push({
          id: item.id,
          lote_id: item.lote_id,
          lote: item.lotes?.codigo || 'N/A',
          validade: item.lotes?.data_validade || '',
          fabricacao: item.lotes?.data_fabricacao || '',
          quantidade: item.quantidade || 0,
        });
      });

      Object.keys(batchesByProduct).forEach((prodId) => {
        batchesByProduct[parseInt(prodId)].sort((a, b) => {
          const dateA = new Date(a.validade).getTime();
          const dateB = new Date(b.validade).getTime();
          return dateA - dateB;
        });
      });

      setBatches(batchesByProduct);
    } catch (e) {
      handleError(e, { domain: 'produtos', operation: 'loadBatches', showToast: false });
    }
  };

  const fetchSetores = async () => {
    try {
      const { data, error } = await supabase
        .from('setores')
        .select('nome, ativo')
        .eq('ativo', true)
        .order('nome');
      if (error) throw error;
      // Filter out empty or null values
      const nomes = (data || [])
        .map((s: any) => s.nome)
        .filter((nome: string) => nome && nome.trim() !== '');
      setSetores(['Todos', ...nomes]);
      if (!nomes.includes('Natal')) {
        // apenas atualiza UI; criação real disponível no formulário
      }
    } catch (e) {
      handleError(e, { domain: 'produtos', operation: 'loadSetores', showToast: false });
    }
  };

  const fetchProdutos = async () => {
    if (!hasData) {
      setProdutos([]);
      return;
    }

    await withTrace('produtos.carregar', async () => {
      const startTime = performance.now();
      try {
        const setorDb = normalizeSetorForDb(setorSelecionado);

        let query = supabase
          .from('vw_produtos_estoque_lojas')
          .select('*')
          .eq('loja_id', storeId)
          .order('nome');

        if (setorSelecionado !== 'Todos') {
          query = query.eq('setor', setorDb);
        }

        const { data, error } = await query;

        if (error) {
          handleError(error, { domain: 'produtos', operation: 'fetchProdutos', showToast: false });
          toast({ title: 'Erro ao carregar produtos', variant: 'destructive' });
          return;
        }

        // Buscar categorias para mapear o objeto completo
        const { data: categoriasData } = await supabase
          .from('categorias')
          .select('*');

        const produtosFormatados: ProdutoComCategoria[] = (data || [])
          // Filter out 'inactive' (archived) products unless showing archived
          .filter((item: any) => (showArchived ? true : item.ativo === true))
          .map((item) => {
            const categoria = categoriasData?.find(
              (c) => c.id === item.categoria_id,
            );

            return {
              id: item.produto_master_id,
              nome: item.nome,
              descricao: '',
              categoria_id: item.categoria_id,
              preco_custo: item.preco_custo,
              codigo_interno: item.codigo_interno,
              unidade_medida: item.unidade_medida,
              ativo: item.ativo,
              setor: item.setor,
              foto_url: item.foto_url,
              categoria: categoria,
              quantidade_atual: item.quantidade_atual,
              quantidade_minima: item.quantidade_minima,
              quantidade_maxima: item.quantidade_maxima,
              oculto: item.oculto ?? false,
              dias_validade: item.dias_validade,
            };
          });

        setProdutos(produtosFormatados);
        const durationMs = Math.round(performance.now() - startTime);
        wideInfo('produtos.carregados', 'Produtos carregados com sucesso', {
          attributes: {
            'result_count': produtosFormatados.length,
            'duration_ms': durationMs,
            'filtro.setor': setorSelecionado,
          },
        });
        recordOperation('produtos.carregar');
        recordOperationDuration('produtos.carregar', durationMs);
      } catch (error) {
        const durationMs = Math.round(performance.now() - startTime);
        handleError(error, { domain: 'produtos', operation: 'fetchProdutosFatal', showToast: false });
        toast({ title: 'Erro ao processar produtos', variant: 'destructive' });
        wideError('produtos.erro', 'Erro ao carregar produtos', {
          attributes: {
            'error.message': error instanceof Error ? error.message : String(error),
            'duration_ms': durationMs,
          },
        });
        recordError('produtos_carregar', 'carregar');
      }
    }, telemetryAttrs);
  };

  // Fetch batches for all products in counting mode
  const fetchBatchesForProducts = async () => {
    if (!storeId || !modoContagem) return;

    try {
      // Cada etiqueta = uma caixa física. 10 caixas do mesmo lote = 10 linhas.
      // Filtra apenas produtos ATIVOS (os que estão na lista carregada).
      const activePids = produtos.map(p => p.id);
      if (activePids.length === 0) return;

      const { data, error } = await (supabase as any)
        .from('etiquetas_qr')
        .select('uid, produto_master_id, lote_id, quantidade_disponivel, lote_codigo_snapshot, lote_validade_snapshot')
        .eq('loja_atual_id', storeId)
        .eq('status', 'recebida')
        .gt('quantidade_disponivel', 0)
        .in('produto_master_id', activePids);

      if (error) {
        handleError(error, { domain: 'produtos', operation: 'fetchLotes', showToast: false });
        return;
      }

      const batchesByProduct: Record<number, Batch[]> = {};
      (data || []).forEach((item: any) => {
        const prodId = item.produto_master_id;
        if (!prodId) return;
        if (!batchesByProduct[prodId]) batchesByProduct[prodId] = [];
        batchesByProduct[prodId].push({
          id: item.uid,
          lote_id: item.lote_id || '',
          lote: item.lote_codigo_snapshot || '—',
          validade: item.lote_validade_snapshot || '',
          fabricacao: '',
          quantidade: Number(item.quantidade_disponivel) || 0,
        });
      });

      // FEFO: ordena por validade dentro de cada produto
      Object.keys(batchesByProduct).forEach((prodId) => {
        batchesByProduct[parseInt(prodId)].sort((a, b) =>
          new Date(a.validade).getTime() - new Date(b.validade).getTime()
        );
      });

      setBatches(batchesByProduct);
    } catch (error) {
      handleError(error, { domain: 'produtos', operation: 'fetchLotesCatch', showToast: false });
    }
  };

  // Dá saída de uma caixa individual na contagem — usa bipar_lote_scanner(saida)
  // para seguir o mesmo trilho do scanner: status etiqueta + movimentação + estoque_lotes.
  const darSaidaCaixa = async (produtoId: number, batch: Batch) => {
    if (!storeId) return;
    try {
      const { data, error } = await (supabase.rpc as any)('bipar_lote_scanner', {
        p_loja_id: storeId,
        p_tipo: 'saida',
        p_itens: [{
          id: batch.id,
          pid: produtoId,
          uid: batch.id,
          lote_id: batch.lote_id || null,
          qty: batch.quantidade,
          tipo_embalagem: null,
          embalagem_nome: null,
          lote: batch.lote || null,
          payload: null,
        }],
      });
      if (error) throw error;
      const rpc = data as any;
      const resultado = rpc?.resultados?.[0];
      if (resultado?.ok === false) throw new Error(resultado.erro || 'Falha na saída');

      // Remove a caixa da UI imediatamente
      setBatches(prev => ({
        ...prev,
        [produtoId]: (prev[produtoId] || []).filter(b => b.id !== batch.id),
      }));
      setProdutos(prev =>
        prev.map(p =>
          p.id === produtoId
            ? { ...p, quantidade_atual: Math.max(0, (p.quantidade_atual || 0) - batch.quantidade) }
            : p,
        ),
      );
      toast({ title: `Saída — caixa ${batch.id.slice(0, 8)} · lote ${batch.lote}` });
    } catch (e) {
      handleError(e, { domain: 'produtos', operation: 'saidaCaixa', showToast: false });
      toast({ title: 'Erro ao dar saída da caixa', variant: 'destructive' });
    }
  };

  // Fetch batches when counting mode is active and products are loaded
  useEffect(() => {
    if (modoContagem && produtos.length > 0 && storeId) {
      fetchBatchesForProducts();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [modoContagem, produtos.length, storeId]);

  const ajustarQuantidade = async (
    produtoId: number,
    delta: number,
    estoqueLoteId?: string,
  ) => {
    if (estoqueLoteId) {
      const produtoAnterior =
        produtos.find((p) => p.id === produtoId)?.quantidade_atual || 0;

      const currentBatch = batches[produtoId]?.find(
        (b) => b.id === estoqueLoteId,
      );
      const batchAnterior = currentBatch?.quantidade || 0;
      const batchNova = Math.max(0, batchAnterior + delta);
      const effectiveDelta = batchNova - batchAnterior;
      const produtoNovo = Math.max(0, produtoAnterior + effectiveDelta);

      setBatches((prev) => {
        const prodBatches = prev[produtoId] || [];
        const newBatches = prodBatches.map((b) =>
          b.id === estoqueLoteId ? { ...b, quantidade: batchNova } : b,
        );
        return { ...prev, [produtoId]: newBatches };
      });

      setProdutos((prev) =>
        prev.map((p) =>
          p.id === produtoId ? { ...p, quantidade_atual: produtoNovo } : p,
        ),
      );

      const key = `${produtoId}_${estoqueLoteId}`;
      const sess = editSessionsRef.current[key];
      if (!sess) {
        editSessionsRef.current[key] = {
          startTotal: produtoAnterior,
          lastTotal: produtoNovo,
          startBatch: batchAnterior,
          lastBatch: batchNova,
        };
      } else {
        sess.lastTotal = produtoNovo;
        sess.lastBatch = batchNova;
      }
      scheduleCommit(key);
    } else {
      const anterior =
        produtos.find((p) => p.id === produtoId)?.quantidade_atual || 0;
      const novaQuantidade = Math.max(0, anterior + delta);
      setProdutos((prev) =>
        prev.map((p) =>
          p.id === produtoId ? { ...p, quantidade_atual: novaQuantidade } : p,
        ),
      );

      const key = `${produtoId}`;
      const sess = editSessionsRef.current[key];
      if (!sess) {
        editSessionsRef.current[key] = {
          startTotal: anterior,
          lastTotal: novaQuantidade,
        };
      } else {
        sess.lastTotal = novaQuantidade;
      }
      scheduleCommit(key);
    }
  };

  const definirQuantidade = async (produtoId: number, nova: number) => {
    const anterior =
      produtos.find((p) => p.id === produtoId)?.quantidade_atual || 0;
    const novaQuantidade = Math.max(0, nova);
    setProdutos((prev) =>
      prev.map((p) =>
        p.id === produtoId ? { ...p, quantidade_atual: novaQuantidade } : p,
      ),
    );
    const key = String(produtoId);
    const sess = editSessionsRef.current[key];
    if (!sess) {
      editSessionsRef.current[key] = {
        startTotal: anterior,
        lastTotal: novaQuantidade,
      };
    } else {
      sess.lastTotal = novaQuantidade;
    }
    scheduleCommit(key, 100); // Commit fast for manual entry
  };

  useEffect(() => {
    const timers = timersRef.current;
    const editSessions = editSessionsRef.current;
    return () => {
      const keys = Object.keys(editSessions);
      keys.forEach((key) => {
        if (timers[key]) {
          clearTimeout(timers[key]);
          delete timers[key];
        }
        delete editSessions[key];
        setPendingConfirm((prev) => ({ ...prev, [key]: false }));
      });
    };
  }, []);

  // Filtrar produtos baseado na pesquisa
  const produtosFiltrados = useMemo(() => {
    return produtos.filter((produto) => {
