  // Editor admin do item: persiste SOMENTE setor + unidade (sem tocar em estoque/preço/nome).
  const salvarSetorUnidade = async (produto: ProdutoComCategoria) => {
    if (produto.ativo === false) return; // regra: nunca alterar produto inativo
