  const saveProduct = async (produto: Partial<ProdutoComCategoria>) => {
    if (!produto.nome) {
      toast({ title: 'Nome do produto é obrigatório', variant: 'destructive' });
      return;
    }

    if (!hasData) {
      toast({ title: 'Selecione uma loja primeiro', variant: 'destructive' });
      return;
    }

    const startTime = performance.now();
    const operacao = produto.id ? 'update' : 'insert';

    // Preparar dados para o catálogo mestre (sem loja_id)
    const productMasterData = {
      nome: produto.nome,
      nome_normalizado: produto.nome.trim().toLowerCase(),
      descricao: produto.descricao,
      codigo_interno: produto.codigo_interno,
      preco_custo: produto.preco_custo,
      unidade_medida: produto.unidade_medida || 'unidade',
      ativo: produto.ativo ?? true,
      setor: normalizeSetorForDb(produto.setor || setorSelecionado),
      foto_url: produto.foto_url,
      dias_validade: produto.dias_validade,
    };

    let produtoId = produto.id;

    if (produto.id) {
      // Atualizar produto existente no catálogo mestre
      const { error } = await supabase
        .from('produtos_master') // Tabela Mestre
        .update(productMasterData)
        .eq('id', produto.id);

      if (error) {
        handleError(error, { domain: 'produtos', operation: 'updateProductMaster', showToast: false });
        toast({ title: 'Erro ao atualizar produto', variant: 'destructive' });
        wideError('produto.erro', 'Erro ao atualizar produto', {
          attributes: {
            'error.message': error.message,
            'produto.operacao': operacao,
            'duration_ms': Math.round(performance.now() - startTime),
          },
        });
        recordError('produto_salvar', operacao);
        return;
      }
    } else {
      // Criar novo produto no catálogo mestre
      const { data, error } = await supabase
        .from('produtos_master')
        .insert(productMasterData)
        .select('id')
        .single();

      if (error) {
        handleError(error, { domain: 'produtos', operation: 'createProductMaster', showToast: false });
        toast({ title: 'Erro ao criar produto', variant: 'destructive' });
        wideError('produto.erro', 'Erro ao criar produto', {
          attributes: {
            'error.message': error.message,
            'produto.operacao': operacao,
            'duration_ms': Math.round(performance.now() - startTime),
          },
        });
        recordError('produto_salvar', operacao);
        return;
      }

      produtoId = data.id;

      // Log de criação
      try {
        const resolveUsuarioId = async (): Promise<number | null> => {
          const { data: rpcId } = await supabase.rpc(
            'get_usuario_id_from_auth',
            { user_uuid: user?.id },
          );
          return (rpcId as number) || null;
        };
        const usuarioIdData = await resolveUsuarioId();

        await supabase.from('movimentacoes').insert({
          produto_master_id: produtoId, // Novo campo
          tipo_movimentacao: 'cadastro',
          quantidade: 0,
          usuario_id: usuarioIdData,
          motivo: 'novo_produto',
          observacoes: `novo produto [${productMasterData.nome}] criado.`,
          data_movimentacao: new Date().toISOString(),
          loja_id: storeId,
        });
      } catch {
        /* intentional */
      }
    }

    // Salvar dados de estoque (vínculo loja -> mestre)
    if (
      produtoId &&
      (produto.quantidade_atual !== undefined ||
        produto.quantidade_minima !== undefined ||
        produto.quantidade_maxima !== undefined)
    ) {
      const estoqueData = {
        produto_master_id: produtoId, // USAR CAMPO NOVO
        loja_id: storeId,
        quantidade_atual: produto.quantidade_atual || 0,
        // ?? para não sobrescrever mínimo 0 legítimo (calculado por demanda)
        quantidade_minima: produto.quantidade_minima ?? 0,
        quantidade_maxima: produto.quantidade_maxima || 100,
        updated_at: new Date().toISOString(),
      };

      const { error: estoqueError } = await supabase
        .from('estoque')
        .upsert(estoqueData, { onConflict: 'produto_master_id,loja_id' }); // Constraint correta

      if (estoqueError) {
        handleError(estoqueError, { domain: 'produtos', operation: 'saveEstoque', showToast: false });
        toast({
          title: 'Produto salvo, mas erro ao atualizar estoque',
          variant: 'destructive',
        });
      }
    }

    const durationMs = Math.round(performance.now() - startTime);
    wideInfo('produto.salvo', 'Produto salvo com sucesso', {
      attributes: {
        'produto.nome': produto.nome || '',
        'produto.operacao': operacao,
        'duration_ms': durationMs,
      },
    });
    recordOperation('produto.salvar');
    recordOperationDuration('produto.salvar', durationMs);

    toast({ title: 'Produto salvo com sucesso!' });
    fetchProdutos();
    setEditingProduct(null);
    setShowNewProduct(false);
    setNewProduct({
      nome: '',
      descricao: '',
      unidade_medida: 'unidade',
      ativo: true,
      setor: setorSelecionado,
    });
  };

  const fetchProductHistory = async (productId: number) => {
