  const deleteProduct = async (id: number) => {
    if (!hasData) {
      toast({ title: 'Selecione uma loja primeiro', variant: 'destructive' });
      return;
    }

    if (!isAdmin()) {
      toast({
        title: 'Acesso Negado',
        description:
          "Apenas administradores podem arquivar produtos do Catálogo Global. Utilize o botão de 'Ocultar' (Olho) para removê-lo da sua loja.",
        variant: 'destructive',
      });
      return;
    }

    const productName = produtos.find((p) => p.id === id)?.nome || '';

    if (
      confirm(
        `ADMIN: Tem certeza que deseja ARQUIVAR o produto "${productName}"? Ele ficará indisponível para TODAS AS LOJAS.`,
      )
    ) {
      try {
        const resolveUsuarioId = async (): Promise<number | null> => {
          const { data: rpcId } = await supabase.rpc(
