          quantidade: 0,
          usuario_id: usuarioIdData,
          motivo: 'produto_arquivado',
          observacoes: `produto [${productName}] arquivado (soft-delete) do catálogo mestre.`,
          data_movimentacao: new Date().toISOString(),
          loja_id: storeId,
        });

        toast({
          title: 'Produto arquivado com sucesso!',
