  const uploadImage = async (file: File, productId?: number) => {
    try {
      setUploadingImage(productId || -1);

      const fileExt = file.name.split('.').pop();
      const fileName = `${Date.now()}.${fileExt}`;
      const filePath = `produtos/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('produto-fotos')
        .upload(filePath, file);

      if (uploadError) {
        throw uploadError;
      }

      const {
        data: { publicUrl },
      } = supabase.storage.from('produto-fotos').getPublicUrl(filePath);

      return publicUrl;
    } catch (error) {
      handleError(error, { domain: 'produtos', operation: 'uploadImage', showToast: false });
      toast({
        title: 'Erro ao fazer upload da imagem',
        variant: 'destructive',
