  const generateAndPrintHTML = (
    title: string,
    items: ItemRelatorio[],
    groupedBySector: boolean,
  ) => {
    const dateStr = new Date().toLocaleDateString('pt-BR', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric',
    });
    const timeStr = new Date().toLocaleTimeString('pt-BR', {
      hour: '2-digit',
      minute: '2-digit',
    });

    // Agrupar itens
    const groups: Record<string, Record<string, ItemRelatorio[]>> = {}; // Setor -> Categoria -> Itens

    items.forEach((item) => {
      const gSetor = item.setor || 'Outros';
      const gCat = item.categoria || 'Sem Categoria';

      if (!groups[gSetor]) groups[gSetor] = {};
      if (!groups[gSetor][gCat]) groups[gSetor][gCat] = [];

      groups[gSetor][gCat].push(item);
    });

    // Ordenar setores e categorias
    const sortedSetores = Object.keys(groups).sort();

    let contentHTML = '';

    sortedSetores.forEach((setorName) => {
      const categoriasDoSetor = groups[setorName];
      const sortedCategorias = Object.keys(categoriasDoSetor).sort();

      // Cabeçalho do Setor (se estiver agrupando por setor, ou se for apenas um setor mas quisermos mostrar)
      contentHTML += `<div class="sector-header">${setorName.toUpperCase()}</div>`;

      sortedCategorias.forEach((catName) => {
        contentHTML += `
          <div class="category-header">${catName.toUpperCase()}</div>
          <table class="items-table">
            <thead>
              <tr>
                <th style="width: 10%">COD</th>
                <th style="width: 40%">PRODUTO</th>
                <th style="width: 10%">UN</th>
                <th style="width: 15%">QTD. SISTEMA</th>
                <th style="width: 25%">CONTAGEM FÍSICA</th>
              </tr>
            </thead>
            <tbody>
        `;

        const catItems = categoriasDoSetor[catName].sort((a, b) =>
          a.nome.localeCompare(b.nome),
        );

        catItems.forEach((item) => {
          contentHTML += `
            <tr>
              <td class="center" style="font-size: 8px; color: #666;">${item.codigo_interno || '-'}</td>
              <td class="product-name">${item.nome}</td>
              <td class="center">${item.unidade}</td>
              <td class="center quantity-system">${item.quantidade_sistema !== undefined && item.quantidade_sistema !== null ? item.quantidade_sistema : 0}</td>
              <td class="write-area"></td>
            </tr>
          `;
