import React, { useEffect, useLayoutEffect, useRef, useState } from "react";
import { useIsMobile } from "@/shared/hooks/use-mobile";
import { LogOut, Leaf, Sun, Moon } from "lucide-react";
import { categories } from "./menuItems";
import { useNavigate } from "react-router-dom";
import { useLocation } from "react-router-dom";
import { useAuth } from "@/shared/hooks/useAuth";
import { Button } from "@/shared/ui/button";
import { MiaGreetingCard } from "@/features/mia/ui/MiaGreetingCard";
// MiaMobileSheet removido — clique navega pra /mia
import { useSystemAnnouncements } from "@/features/announcements";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/shared/ui/dropdown-menu";
import { Avatar, AvatarFallback } from "@/shared/ui/avatar";
import { StoreSelector } from "@/shared/ui/DashboardStoreSelector";
import { toast } from "sonner";
import { cn } from "@/shared/lib/utils";
import { useTheme } from "next-themes";
import { wideError } from "@/shared/lib/telemetry/wide-events";

type FeatureCardProps = {
  title: string;
  icon: React.ElementType;
  onClick: () => void;
};

function FeatureCard({ title, icon: Icon, onClick }: FeatureCardProps) {
  const slug = title.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
  return (
    <button
      data-mia-action={`abrir-feature-${slug}`}
      data-mia-feature-title={title}
      onClick={onClick}
      className="group flex flex-col items-center gap-2 p-2 transition-all duration-300 active:scale-95"
    >
      {/* Arched Card Design mimicking the store shelves */}
      <div
        className={cn(
          'relative flex items-center justify-center h-[80px] w-[72px]',
          'rounded-t-[36px] rounded-b-[12px]', // Arch shape
          'bg-white dark:bg-[#1A1A1A]', // Pure white background for contrast
          'border-[2px] border-[#C5A065] dark:border-[#C5A065]/50', // Gold border for premium highlight
          'shadow-[0_8px_20px_-6px_rgba(87,113,91,0.25),0_4px_8px_-2px_rgba(197,160,101,0.15)]', // Richer shadow with green and gold tones
          'group-hover:border-[#57715B] dark:group-hover:border-[#57715B] group-hover:shadow-[0_12px_24px_-6px_rgba(87,113,91,0.4)] transition-all duration-300',
        )}
      >
        {/* Inner Arch Accent (Depth) - Subtle Green Tint */}
        <div className="absolute inset-[3px] rounded-t-[30px] rounded-b-[9px] border border-[#57715B]/10 dark:border-white/5 bg-[#57715B]/[0.02]" />

        {/* Bottom Gold Accent Line */}
        <div className="absolute bottom-3 w-8 h-1 bg-[#C5A065] rounded-full opacity-40" />

        <Icon
          className="h-8 w-8 text-[#57715B] dark:text-[#8FA893] group-hover:scale-110 transition-transform duration-300 relative z-10 drop-shadow-sm"
          strokeWidth={1.5}
        />
      </div>

      <span className="text-[11px] font-bold tracking-wide text-[#2D362E] dark:text-[#E6DCCF] text-center leading-tight max-w-[80px] line-clamp-2 uppercase drop-shadow-sm group-hover:text-[#57715B] transition-colors">
        {title}
      </span>
    </button>
  );
}


export default function MobileHome() {
  const isMobile = useIsMobile();
  const navigate = useNavigate();
  const location = useLocation();
  const containerRef = useRef<HTMLDivElement | null>(null);
  const { theme, setTheme } = useTheme();
  const [serverVersion, setServerVersion] = useState<string | null>(null);

  useEffect(() => {
    fetch(`/version.json?t=${Date.now()}`)
      .then(res => res.json())
      .then(data => setServerVersion(data.version))
      .catch(err => wideError('dashboard.mobile_home.version_fetch_error', 'Falha ao buscar versão do servidor', { attributes: { 'error.message': err instanceof Error ? err.message : String(err), 'operation.name': 'fetchServerVersion' } }));
  }, []);

  const getInitialIndex = () => {
    const params = new URLSearchParams(location.search);
    const cat = (params.get('category') || '').toLowerCase();
    const idxByParam = categories.findIndex(
      (c) => c.name.toLowerCase() === cat,
    );
    if (idxByParam >= 0) return idxByParam;
    const estoqueIdx = categories.findIndex(
      (c) => c.name.toLowerCase() === 'estoque',
    );
    return estoqueIdx >= 0 ? estoqueIdx : 0;
  };

  const [pageIndex, setPageIndex] = useState<number>(getInitialIndex());
  const { user, signOut } = useAuth();
  const { unreadCount: miaUnreadCount } = useSystemAnnouncements();

  useLayoutEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const onScroll = () => {
      const w = el.clientWidth;
      const idx = Math.round(el.scrollLeft / w);
      setPageIndex(Math.max(0, Math.min(categories.length - 1, idx)));
    };
    el.addEventListener('scroll', onScroll, { passive: true });
    const initialIdx = getInitialIndex();
    const w = el.clientWidth;
    el.scrollTo({ left: w * initialIdx, behavior: 'auto' });
    setPageIndex(initialIdx);
    return () => el.removeEventListener('scroll', onScroll);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.search]);

  if (!isMobile) return null;

  return (
    <div className="flex flex-col h-[100dvh] bg-white dark:bg-[#0A0A0A] overflow-hidden relative font-sans">
      {/* Store Awning Stripe Effect (Top Border) */}
      <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50" />

      {/* Animated Plant Background Elements - Restored Pulse */}
      <div
        className="absolute top-[-5%] right-[-10%] w-[300px] h-[300px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse"
        style={{ animationDuration: '10s' }}
      >
        <Leaf className="w-full h-full text-[#57715B] rotate-12" />
      </div>
      <div
        className="absolute bottom-[-10%] left-[-15%] w-[400px] h-[400px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse delay-1000"
        style={{ animationDuration: '12s' }}
      >
        <Leaf className="w-full h-full text-[#57715B] -rotate-45" />
      </div>

      {/* Soft Ambient Glows */}
      <div className="absolute top-[20%] left-[10%] w-[200px] h-[200px] bg-[#57715B]/5 rounded-full blur-[80px] pointer-events-none" />
      <div className="absolute bottom-[30%] right-[10%] w-[250px] h-[250px] bg-[#C5A065]/5 rounded-full blur-[80px] pointer-events-none" />

      {/* Header Bar */}
      <div className="flex justify-between items-center px-6 pt-8 pb-2 z-20">
        {/* Logo Placement */}
        <div className="flex items-center gap-3">
          <div className="relative h-12 w-auto">
            <img
              src="/logo sistema/01. Reduzida 5.png"
              alt="Momma"
              className="h-full w-auto object-contain dark:hidden drop-shadow-sm"
            />
            <img
              src="/logo sistema/01. Reduzida branco.png"
              alt="Momma"
              className="h-full w-auto object-contain hidden dark:block drop-shadow-sm"
            />
          </div>
        </div>

        {/* Right Actions */}
        <div className="flex items-center gap-3">
          {/* Store Selector */}
          <StoreSelector />

          {/* Theme Toggle */}
          <Button
            data-mia-action="toggle-tema"
            variant="ghost"
            size="icon"
            onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
            className="h-10 w-10 rounded-full bg-[#E6DCCF]/40 dark:bg-white/10 border border-[#57715B]/10 dark:border-white/5 hover:bg-[#57715B]/10 transition-all"
          >
            <Sun className="h-5 w-5 text-[#57715B] dark:text-[#8FA893] rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0" />
            <Moon className="absolute h-5 w-5 text-[#8FA893] rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100" />
          </Button>

          {/* Profile Menu */}
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                data-mia-action="abrir-menu-perfil"
                variant="ghost"
                className="h-10 w-10 rounded-full p-0 hover:bg-transparent relative"
              >
                <Avatar className="h-10 w-10 ring-2 ring-[#E6DCCF] dark:ring-zinc-700 shadow-md transition-transform active:scale-95">
                  <AvatarFallback className="bg-[#E6DCCF] text-[#57715B] font-bold text-sm border border-[#C5A065]/20">
                    {(user?.user_metadata?.nome || 'U')
