      <div data-mia-action="abrir-mia" className="px-6 mb-8 z-10 mt-6">
        <MiaGreetingCard
          onTap={() => navigate('/mia')}
          unreadAnnouncements={miaUnreadCount}
        />
      </div>

      {/* Main Content Area - Full Screen Width */}
      <div className="flex-1 relative z-10 flex flex-col">
        {/* Category Title & Navigation */}
        <div className="px-8 mb-4 flex items-center justify-between">
          <h3 className="text-lg font-bold text-[#57715B] dark:text-white tracking-wide uppercase">
            {categories[pageIndex]?.name}
          </h3>

          {/* Modern Pill Indicator */}
          <div className="flex items-center gap-1 bg-[#E6DCCF]/40 dark:bg-zinc-800/50 rounded-full px-2 py-1">
            {categories.map((_, i) => (
              <div
                key={i}
                className={cn(
                  'h-1.5 rounded-full transition-all duration-500 ease-spring',
                  i === pageIndex
                    ? 'w-6 bg-[#57715B]'
                    : 'w-1.5 bg-[#57715B]/20 dark:bg-zinc-600',
                )}
              />
            ))}
          </div>
        </div>

        {/* Horizontal Scroll Container - Full Width */}
        <div
          ref={containerRef}
          className="flex-1 overflow-x-auto snap-x snap-mandatory flex scrollbar-hide pb-8 touch-pan-x"
          style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
        >
          {categories.map((cat, idx) => (
            <div
              key={idx}
              className={cn(
                'min-w-full snap-center px-4 transition-all duration-500 ease-out',
                'snap-always',
                // Optimized focus effect: Removed blur, using only opacity and scale
                idx === pageIndex
                  ? 'opacity-100 scale-100'
                  : 'opacity-40 scale-95',
              )}
              style={{ scrollSnapStop: 'always' }}
            >
              <div className="grid grid-cols-3 sm:grid-cols-4 gap-y-8 gap-x-2 place-items-center content-start">
                {cat.items.map((item) => (
                  <FeatureCard
                    key={item.title}
                    title={item.title}
                    icon={item.icon}
                    onClick={() => navigate(item.url)}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Mobile Footer */}
      <div className="pt-4 pb-[calc(1rem+env(safe-area-inset-bottom))] flex flex-col items-center justify-center gap-2 z-10 relative w-full mt-auto">
        <div className="flex items-center gap-2 drop-shadow-[0_1px_1px_rgba(255,255,255,0.5)] dark:drop-shadow-none">
          <img
            src="/logo sistema/01. Reduzida 5.png"
