            className="h-5 w-auto object-contain dark:hidden opacity-90"
          />
          <img
            src="/logo sistema/01. Reduzida branco.png"
            alt="Momma"
            className="h-5 w-auto object-contain hidden dark:block opacity-90"
          />
          <span className="text-xs font-bold text-[#4A3728] dark:text-[#E6DCCF] uppercase tracking-wider">
            sistema GIDAPE
          </span>
        </div>
      </div>

    </div>
  );
}

