          'group-hover:border-[#57715B] dark:group-hover:border-[#57715B] group-hover:shadow-[0_16px_32px_-8px_rgba(87,113,91,0.4)] transition-all duration-300',
        )}
      >
        <div className="absolute inset-[4px] rounded-t-[48px] rounded-b-[14px] border border-[#57715B]/10 dark:border-white/5 bg-[#57715B]/[0.02]" />
        <div className="absolute bottom-4 w-12 h-1.5 bg-[#C5A065] rounded-full opacity-40" />
        <Icon
          className="h-12 w-12 text-[#57715B] dark:text-[#8FA893] group-hover:scale-110 transition-transform duration-300 relative z-10 drop-shadow-sm"
          strokeWidth={1.5}
        />
      </div>

      <span className="text-sm font-bold tracking-wide text-[#2D362E] dark:text-[#E6DCCF] text-center leading-tight max-w-[120px] line-clamp-2 uppercase drop-shadow-sm group-hover:text-[#57715B] transition-colors">
        {title}
      </span>
    </button>
  );
}

export default function TabletHome() {
  const isTablet = useIsTablet();
  const navigate = useNavigate();
  const location = useLocation();
  const containerRef = useRef<HTMLDivElement | null>(null);
  const { theme, setTheme } = useTheme();
  const [serverVersion, setServerVersion] = useState<string | null>(null);

  useEffect(() => {
    fetch(`/version.json?t=${Date.now()}`)
      .then(res => res.json())
      .then(data => setServerVersion(data.version))
      .catch(err => wideError('dashboard.tablet_home.version_fetch_error', 'Falha ao buscar versão do servidor', { attributes: { 'error.message': err instanceof Error ? err.message : String(err), 'operation.name': 'fetchServerVersion' } }));
  }, []);

  const getInitialIndex = () => {
    const params = new URLSearchParams(location.search);
    const cat = (params.get('category') || '').toLowerCase();
    const idxByParam = categories.findIndex(
      (c) => c.name.toLowerCase() === cat,
    );
    if (idxByParam >= 0) return idxByParam;
    const estoqueIdx = categories.findIndex(
      (c) => c.name.toLowerCase() === 'estoque',
    );
    return estoqueIdx >= 0 ? estoqueIdx : 0;
  };

  const [pageIndex, setPageIndex] = useState<number>(getInitialIndex());
  const { user, userProfile, signOut } = useAuth();
  const { unreadCount: miaUnreadCount } = useSystemAnnouncements();

  useLayoutEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const onScroll = () => {
      const w = el.clientWidth;
      const idx = Math.round(el.scrollLeft / w);
      setPageIndex(Math.max(0, Math.min(categories.length - 1, idx)));
    };
    el.addEventListener('scroll', onScroll, { passive: true });
    const initialIdx = getInitialIndex();
    const w = el.clientWidth;
    el.scrollTo({ left: w * initialIdx, behavior: 'auto' });
    setPageIndex(initialIdx);
    return () => el.removeEventListener('scroll', onScroll);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.search]);

  if (!isTablet) return null;

  return (
    <div className="flex flex-col h-[100dvh] bg-white dark:bg-[#0A0A0A] overflow-hidden relative font-sans">
      <div className="absolute top-0 left-0 right-0 h-2 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_28px,#ffffff_28px,#ffffff_56px)] opacity-80 z-50" />

      <div
        className="absolute top-[-5%] right-[-8%] w-[440px] h-[440px] opacity-[0.04] dark:opacity-[0.06] pointer-events-none animate-pulse"
        style={{ animationDuration: '10s' }}
      >
        <Leaf className="w-full h-full text-[#57715B] rotate-12" />
      </div>
      <div
        className="absolute bottom-[-10%] left-[-12%] w-[560px] h-[560px] opacity-[0.04] dark:opacity-[0.06] pointer-events-none animate-pulse delay-1000"
        style={{ animationDuration: '12s' }}
      >
        <Leaf className="w-full h-full text-[#57715B] -rotate-45" />
      </div>

      <div className="absolute top-[20%] left-[10%] w-[300px] h-[300px] bg-[#57715B]/5 rounded-full blur-[100px] pointer-events-none" />
      <div className="absolute bottom-[30%] right-[10%] w-[360px] h-[360px] bg-[#C5A065]/5 rounded-full blur-[100px] pointer-events-none" />

      <div className="flex justify-between items-center px-12 pt-10 pb-3 z-20">
        <div className="flex items-center gap-4">
          <div className="relative h-16 w-auto">
            <img
              src="/logo sistema/01. Reduzida 5.png"
              alt="Momma"
              className="h-full w-auto object-contain dark:hidden drop-shadow-sm"
            />
            <img
              src="/logo sistema/01. Reduzida branco.png"
              alt="Momma"
              className="h-full w-auto object-contain hidden dark:block drop-shadow-sm"
            />
          </div>
        </div>

        <div className="flex items-center gap-4">
          <StoreSelector />

          <Button
            variant="ghost"
            size="icon"
            onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
            className="h-12 w-12 rounded-full bg-[#E6DCCF]/40 dark:bg-white/10 border border-[#57715B]/10 dark:border-white/5 hover:bg-[#57715B]/10 transition-all"
          >
            <Sun className="h-6 w-6 text-[#57715B] dark:text-[#8FA893] rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0" />
            <Moon className="absolute h-6 w-6 text-[#8FA893] rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100" />
          </Button>

          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                variant="ghost"
                className="h-12 w-12 rounded-full p-0 hover:bg-transparent relative"
              >
                <Avatar className="h-12 w-12 ring-2 ring-[#E6DCCF] dark:ring-zinc-700 shadow-md transition-transform active:scale-95">
                  <AvatarFallback className="bg-[#E6DCCF] text-[#57715B] font-bold text-base border border-[#C5A065]/20">
                    {(user?.user_metadata?.nome || 'U')
                      .slice(0, 2)
                      .toUpperCase()}
                  </AvatarFallback>
                </Avatar>
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent
              className="w-72 rounded-2xl border-[#E6DCCF] dark:border-zinc-800 bg-white dark:bg-zinc-900 shadow-xl"
              align="end"
              sideOffset={8}
            >
              <DropdownMenuLabel className="font-normal p-4">
                <div className="flex flex-col space-y-1">
                  <p className="text-base font-semibold leading-none text-[#57715B] dark:text-zinc-100">
                    {user?.user_metadata?.nome || userProfile?.nome}
                  </p>
                  <p className="text-xs text-zinc-500">{user?.email}</p>
                </div>
              </DropdownMenuLabel>
              <DropdownMenuSeparator className="bg-[#E6DCCF] dark:bg-zinc-800" />

              <div className="px-2 py-1.5 text-[10px] text-center text-zinc-400 select-none">
                v{String(__APP_VERSION__)} / srv {serverVersion || '...'}
              </div>
              <DropdownMenuSeparator className="bg-[#E6DCCF] dark:bg-zinc-800" />
              <DropdownMenuItem
                className="p-3 m-1 text-red-500 focus:text-red-600 focus:bg-red-50 dark:focus:bg-red-950/30 rounded-xl"
                onClick={async () => {
                  await signOut();
                  toast.success('Até logo!');
                }}
              >
                <LogOut className="mr-2 h-4 w-4" />
                Sair
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      <div className="px-12 mb-10 z-10 mt-6 max-w-[920px] w-full mx-auto">
        <MiaGreetingCard
          onTap={() => navigate('/mia')}
          unreadAnnouncements={miaUnreadCount}
        />
      </div>

      <div className="flex-1 relative z-10 flex flex-col">
        <div className="px-14 mb-6 flex items-center justify-between">
          <h3 className="text-2xl font-bold text-[#57715B] dark:text-white tracking-wide uppercase">
            {categories[pageIndex]?.name}
          </h3>

          <div className="flex items-center gap-1.5 bg-[#E6DCCF]/40 dark:bg-zinc-800/50 rounded-full px-3 py-1.5">
            {categories.map((_, i) => (
              <div
                key={i}
                className={cn(
                  'h-2 rounded-full transition-all duration-500 ease-spring',
                  i === pageIndex
                    ? 'w-8 bg-[#57715B]'
                    : 'w-2 bg-[#57715B]/20 dark:bg-zinc-600',
                )}
              />
            ))}
          </div>
        </div>

        <div
          ref={containerRef}
          className="flex-1 overflow-x-auto snap-x snap-mandatory flex scrollbar-hide pb-10 touch-pan-x"
          style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
        >
          {categories.map((cat, idx) => (
            <div
              key={idx}
              className={cn(
                'min-w-full snap-center px-10 transition-all duration-500 ease-out',
                'snap-always',
                idx === pageIndex
                  ? 'opacity-100 scale-100'
                  : 'opacity-40 scale-95',
              )}
              style={{ scrollSnapStop: 'always' }}
            >
              <div className="grid grid-cols-5 lg:grid-cols-6 gap-y-10 gap-x-4 place-items-center content-start w-full">
                {cat.items.map((item) => (
                  <FeatureCard
                    key={item.title}
                    title={item.title}
                    icon={item.icon}
                    onClick={() => navigate(item.url)}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="pt-4 pb-[calc(1rem+env(safe-area-inset-bottom))] flex flex-col items-center justify-center gap-2 z-10 relative w-full mt-auto">
        <div className="flex items-center gap-2 drop-shadow-[0_1px_1px_rgba(255,255,255,0.5)] dark:drop-shadow-none">
          <img
            src="/logo sistema/01. Reduzida 5.png"
            alt="Momma"
            className="h-6 w-auto object-contain dark:hidden opacity-90"
          />
          <img
            src="/logo sistema/01. Reduzida branco.png"
            alt="Momma"
            className="h-6 w-auto object-contain hidden dark:block opacity-90"
          />
          <span className="text-sm font-bold text-[#4A3728] dark:text-[#E6DCCF] uppercase tracking-wider">
            sistema GIDAPE
          </span>
        </div>
      </div>

    </div>
  );
}

