/**
 * @module features/estoque
 *
 * Feature de controle de estoque: visualização de inventário,
 * registro de movimentações e gestão de compras.
 */

export { default as MovimentacoesPage } from './ui/Movimentacoes.page';
export { default as VerificacaoPerdasPage } from './ui/VerificacaoPerdas.page';
export { default as ScannerPage, ScannerContent } from './ui/Scanner.page';

