1	import { useState, useEffect } from "react";
2	import { FileText, Filter, ArrowLeft, Sun, Moon, Leaf, User as UserIcon, LogOut, ChevronLeft, ChevronRight, Search, X } from "lucide-react";
3	import { Input } from "@/shared/ui/input";
4	import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/shared/ui/table";
5	import { Badge } from "@/shared/ui/badge";
6	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/shared/ui/select";
7	import { supabase } from "@/integrations/supabase/client";
8	import { toast } from "@/shared/hooks/use-toast";
9	import { format } from "date-fns";
10	import { ptBR } from "date-fns/locale";
11	import { useStoreFilter } from "@/shared/hooks/useStoreData";
12	import { PermissionBlur } from "@/shared/ui/PermissionBlur";
13	import { usePermissions } from "@/shared/hooks/usePermissions";
14	import { useIsMobile } from "@/shared/hooks/use-mobile";
15	import { useTheme } from "next-themes";
16	import { useAuth } from "@/hooks/useAuth";
17	import { StoreSelector } from "@/shared/ui/StoreSelector";
18	import { useNavigate } from "react-router-dom";
19	import { cn } from "@/shared/lib/utils";
20	import { Button } from "@/shared/ui/button";
21	import { useMiaMovimentacoesActions } from '@/features/mia/model/hooks';
22	import {
23	  DropdownMenu,
24	  DropdownMenuContent,
25	  DropdownMenuItem,
26	  DropdownMenuLabel,
27	  DropdownMenuSeparator,
28	  DropdownMenuTrigger,
29	} from "@/shared/ui/dropdown-menu";
30	import { Avatar, AvatarFallback } from "@/shared/ui/avatar";
31	
32	interface Movement {
33	  movimentacao_id: number;
34	  tipo_movimentacao: string;
35	  produto_nome: string;
36	  categoria_nome: string;
37	  categoria_emoji: string;
38	  quantidade: number;
39	  quantidade_anterior: number;
40	  quantidade_nova: number;
41	  unidade_medida: string;
42	  usuario_nome: string;
43	  data_movimentacao: string;
44	  motivo: string;
45	  observacoes: string;
46	  codigo_interno: number;
47	  lote_codigo?: string;
48	  lote_validade?: string;
49	}
50	
51	const getRequisicaoText = (observacoes: string | undefined) => {
52	  if (!observacoes) return "Req. Saída";
53	  const match = observacoes.match(/Saída por requisição #(\d+)/);
54	  return match ? `Req #${match[1]}` : "Req. Saída";
55	};
56	
57	export default function Movimentacoes() {
58	  const [movements, setMovements] = useState<Movement[]>([]);
59	  const [isLoading, setIsLoading] = useState(true);
60	  const [sectorFilter, setSectorFilter] = useState<string>("todos");
61	  const [userFilter, setUserFilter] = useState<string>("todos");
62	  const [typeFilter, setTypeFilter] = useState<string>("todos");
63	  const [sectors, setSectors] = useState<string[]>([]);
64	  const [productSearch, setProductSearch] = useState<string>("");
65	  const { hasData, applyStoreFilter, storeId } = useStoreFilter();
66	  const { canViewEstoque, hasPermission, isAdmin } = usePermissions();
67	
68	  const isMobile = useIsMobile();
69	  const { theme, setTheme } = useTheme();
70	  const navigate = useNavigate();
71	  const { userProfile, user, signOut } = useAuth();
72	  const [serverVersion, setServerVersion] = useState<string | null>(null);
73	  const [currentPage, setCurrentPage] = useState(1);
74	  const ITEMS_PER_PAGE = 20;
75	
76	  useMiaMovimentacoesActions({
77	    setSectorFilter,
78	    setProductSearch,
79	    setCurrentPage,
80	    movements,
81	  });
82	
83	  useEffect(() => {
84	    if (hasData) {
85	      fetchSectors();
86	      fetchMovements();
87	    }
88	  }, [hasData, storeId]);
89	
90	  useEffect(() => {
91	    setCurrentPage(1);
92	  }, [sectorFilter, productSearch, userFilter, typeFilter]);
93	
94	  useEffect(() => {
95	    fetchMovements();
96	  }, [currentPage, sectorFilter, storeId, hasData, productSearch]);
97	
98	  useEffect(() => {
99	    if (isMobile) {
100	      fetch(`/version.json?t=${Date.now()}`)
101	        .then(res => res.json())
102	        .then(data => setServerVersion(data.version))
103	        .catch(err => console.error("Failed to fetch server version", err));
104	    }
105	  }, [isMobile]);
106	
107	  const fetchSectors = async () => {
108	    try {
109	      if (!hasData) {
110	        setSectors([]);
111	        return;
112	      }
113	
114	      // Use standard view for sectors
115	      // @ts-expect-error - supabase view type not in generated types
116	      const query = supabase
117	        .from('vw_produtos_estoque_lojas')
118	        .select('setor')
119	        .eq('loja_id', storeId) // Explicitly filter by store
120	        .not('setor', 'is', null);
121	
122	      const { data, error } = await query;
123	
124	      if (error) throw error;
125	
126	      const uniqueSectors = [...new Set(data?.map((p: any) => p.setor) || [])]
127	        .filter(sector => sector && sector.toLowerCase() !== 'compras');
128	      setSectors(uniqueSectors as string[]);
129	    } catch (error) {
130	      console.error('Erro ao carregar setores:', error);
131	    }
132	  };
133	
134	  const fetchMovements = async () => {
135	    try {
136	      if (!hasData) {
137	        setMovements([]);
138	        return;
139	      }
140	
141	      const from = (currentPage - 1) * ITEMS_PER_PAGE;
142	      const to = from + ITEMS_PER_PAGE - 1;
143	
144	      // If there's a product search, prioritize it - search ALL movements without pagination
145	      if (productSearch.trim()) {
146	        const term = productSearch.trim();
147	        let searchQuery = supabase
148	          .from('view_movimentacoes_recentes')
149	          .select('*')
150	          .or(`produto_nome.ilike.%${term}%,codigo_interno_str.ilike.%${term}%,lote_codigo.ilike.%${term}%`)
151	          .order('data_movimentacao', { ascending: false })
152	          .limit(500); // High limit to get comprehensive results for the search
153	
154	        searchQuery = applyStoreFilter(searchQuery);
155	        const { data: searchData, error: searchError } = await searchQuery;
156	
157	        if (searchError) throw searchError;
158	        setMovements(searchData || []);
159	        return;
160	      }
161	
162	      if (sectorFilter !== "todos") {
163	        // Buscar produtos do setor - uses standard view
164	        // @ts-expect-error - supabase view type not in generated types
165	        const produtosQuery = supabase
166	          .from('vw_produtos_estoque_lojas')
167	          .select('produto_master_id, nome')
168	          .eq('loja_id', storeId)
169	          .eq('setor', sectorFilter);
170	
171	        const { data: produtos, error: produtosError } = await produtosQuery;
172	
173	        if (produtosError) throw produtosError;
174	
175	        if (produtos && produtos.length > 0) {
176	          const produtoNomes = produtos.map((p: any) => p.nome);
177	
178	          // Buscar movimentações filtrando pelo nome do produto
179	          let movQuery = supabase
180	            .from('view_movimentacoes_recentes')
181	            .select('*')
182	            .in('produto_nome', produtoNomes)
183	            .order('data_movimentacao', { ascending: false })
184	            .range(from, to);
185	
186	          movQuery = applyStoreFilter(movQuery);
187	          const { data: movData, error: movError } = await movQuery;
188	
189	          if (movError) throw movError;
190	          setMovements(movData || []);
191	        } else {
192	          setMovements([]);
193	        }
194	      } else {
195	        // Buscar todas as movimentações
196	        let allMovQuery = supabase
197	          .from('view_movimentacoes_recentes')
198	          .select('*')
199	          .order('data_movimentacao', { ascending: false })
