                          </Badge>
                        )}
                      </div>
                    )}

                    <div className="flex items-center justify-between mt-2">
                      <div className="flex items-center gap-1.5 flex-wrap">
                        <Badge variant={movement.tipo_movimentacao === 'entrada' ? 'default' : 'destructive'} className="text-[10px] h-5 px-2">
                          {formatMovementType(movement.tipo_movimentacao)}
