                        <span className="text-xs text-zinc-400">{movement.unidade_medida}</span>
                      </div>
                    </div>
                  </div>
                </div>
                <div className="mt-3 pt-3 border-t border-dashed border-zinc-200 dark:border-zinc-800 flex items-center justify-between">
