                  variant="outline"
                  size="sm"
                  onClick={() => setCurrentPage(prev => prev + 1)}
                  disabled={movements.length < ITEMS_PER_PAGE}
                  className="h-9 px-4 rounded-xl border-[#57715B]/20 dark:border-white/10"
