                    <SelectItem value="todos" className="rounded-lg cursor-pointer focus:bg-[#57715B]/10 dark:focus:bg-white/10">Todos os Setores</SelectItem>
                    {sectors.map((sector) => (
                      <SelectItem key={sector} value={sector} className="rounded-lg cursor-pointer focus:bg-[#57715B]/10 dark:focus:bg-white/10">{sector}</SelectItem>
                    ))}
