                </div>
                <Select value={userFilter} onValueChange={setUserFilter} disabled={!!productSearch}>
                  <SelectTrigger className="w-full md:w-[200px] bg-white/60 dark:bg-zinc-900/60 border-[#57715B]/20 dark:border-white/10 rounded-2xl focus:ring-[#57715B]/20 h-10 transition-all hover:bg-white/80 dark:hover:bg-zinc-800/80">
                    <SelectValue placeholder="Filtrar por operador" />
