                    <SelectItem value="entrada" className="rounded-lg cursor-pointer focus:bg-[#57715B]/10 dark:focus:bg-white/10">Entrada</SelectItem>
                    <SelectItem value="saida" className="rounded-lg cursor-pointer focus:bg-[#57715B]/10 dark:focus:bg-white/10">Saída</SelectItem>
