          {/* Main Table Card */}
          <div className="bg-white/70 dark:bg-zinc-900/70 backdrop-blur-xl border border-[#57715B]/10 dark:border-white/5 rounded-[32px] overflow-x-auto shadow-lg shadow-[#57715B]/5">
            <Table>
              <TableHeader className="bg-[#57715B]/5 dark:bg-[#E6DCCF]/5">
                <TableRow className="border-b border-[#57715B]/10 dark:border-white/5 hover:bg-transparent">
                  <TableHead className="font-semibold text-[#57715B] dark:text-[#E6DCCF] text-center py-6 w-[180px]">Data e Hora</TableHead>
                  <TableHead className="font-semibold text-[#57715B] dark:text-[#E6DCCF] py-6">Produto</TableHead>
                  <TableHead className="font-semibold text-[#57715B] dark:text-[#E6DCCF] py-6">Lote</TableHead>
                  <TableHead className="font-semibold text-[#57715B] dark:text-[#E6DCCF] text-center py-6">Tipo</TableHead>
                  <TableHead className="font-semibold text-[#57715B] dark:text-[#E6DCCF] text-center py-6">Qtd. Anterior</TableHead>
                  <TableHead className="font-semibold text-[#57715B] dark:text-[#E6DCCF] text-center py-6">Movimento</TableHead>
                  <TableHead className="font-semibold text-[#57715B] dark:text-[#E6DCCF] text-center py-6">Qtd. Nova</TableHead>
                  <TableHead className="font-semibold text-[#57715B] dark:text-[#E6DCCF] py-6 rounded-tr-[32px]">Responsável</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredMovements.map((movement) => (
                  <TableRow key={movement.movimentacao_id} className="group border-b border-[#57715B]/5 dark:border-white/5 hover:bg-[#57715B]/5 dark:hover:bg-[#E6DCCF]/5 transition-all duration-200">
                    <TableCell className="text-center font-mono text-xs text-zinc-500 py-4 group-hover:text-[#57715B] dark:group-hover:text-[#E6DCCF] transition-colors">
                      <div className="flex flex-col items-center gap-1">
                        <span className="font-bold text-sm">{format(new Date(movement.data_movimentacao), 'dd/MM/yyyy', { locale: ptBR })}</span>
                        <span className="text-zinc-400">{format(new Date(movement.data_movimentacao), 'HH:mm', { locale: ptBR })}</span>
                      </div>
                    </TableCell>
                    <TableCell className="py-4">
                      <div className="flex items-center gap-3">
                        <span className="text-3xl shrink-0">
                          {movement.categoria_emoji}
                        </span>
                        <div>
                          <div className="font-bold text-[#2D362E] dark:text-[#E6DCCF] text-base">{movement.produto_nome}</div>
                          <div className="text-xs font-medium text-[#57715B]/60 dark:text-[#E6DCCF]/60 uppercase tracking-wider">{movement.categoria_nome}</div>
                        </div>
                      </div>
                    </TableCell>
                    <TableCell className="py-4">
                      {movement.lote_codigo ? (
                        <div className="flex flex-col gap-1">
                          <Badge variant="outline" className="text-xs font-mono px-2 py-0.5 border-[#57715B]/30 text-[#57715B] dark:text-[#E6DCCF] bg-[#57715B]/5 w-fit">
                            {movement.lote_codigo}
                          </Badge>
                          {movement.lote_validade && (
                            <span className="text-[10px] text-zinc-500">
                              Val: {format(new Date(movement.lote_validade + 'T12:00:00'), 'dd/MM/yy', { locale: ptBR })}
                            </span>
                          )}
                        </div>
                      ) : (
                        <span className="text-xs text-zinc-400 italic">Sem lote</span>
                      )}
                    </TableCell>
                    <TableCell className="text-center py-4">
                      <div className="flex flex-col items-center gap-1">
                        <Badge
                          variant="outline"
                          className={cn(
                            "border-0 font-medium px-3 py-1 text-xs uppercase tracking-wide rounded-lg",
                            movement.tipo_movimentacao === 'entrada' ? "bg-green-100/50 text-green-700 dark:bg-green-500/10 dark:text-green-400" :
                              movement.tipo_movimentacao === 'saida' ? "bg-red-100/50 text-red-700 dark:bg-red-500/10 dark:text-red-400" :
                                "bg-zinc-100/50 text-zinc-700 dark:bg-zinc-800/50 dark:text-zinc-400"
                          )}
                        >
                          {formatMovementType(movement.tipo_movimentacao)}
                        </Badge>
                        {(movement.motivo === 'scanner_lote' || movement.motivo === 'saida_inteira') && (
                          <Badge variant="outline" className="text-[10px] h-4 px-1.5 border-[#57715B]/30 text-[#57715B]/70 dark:text-[#E6DCCF]/70">
                            via Scanner
                          </Badge>
                        )}
                        {movement.motivo === 'saida_requisicao' && (
                          <span className="text-[#57715B] bg-[#57715B]/8 rounded-full px-2 py-0.5 text-[10px] font-medium">
                            {getRequisicaoText(movement.observacoes)}
                          </span>
                        )}
                      </div>
                    </TableCell>
                    <TableCell className="text-center font-mono text-sm text-zinc-500 py-4">
                      {movement.quantidade_anterior} <span className="text-xs text-zinc-400">{movement.unidade_medida}</span>
                    </TableCell>
                    <TableCell className="text-center py-4">
                      <span className={cn(
                        "font-mono font-bold text-base px-3 py-1 rounded-lg bg-white/50 dark:bg-black/20",
                        getMovementColor(movement.tipo_movimentacao)
                      )}>
                        {movement.tipo_movimentacao === 'entrada' ? '+' : '-'}{movement.quantidade}
                      </span>
                    </TableCell>
                    <TableCell className="text-center font-mono text-base font-bold text-[#57715B] dark:text-[#8FA893] py-4">
                      {movement.quantidade_nova} <span className="text-xs font-normal text-zinc-400">{movement.unidade_medida}</span>
                    </TableCell>
                    <TableCell className="text-sm text-zinc-600 dark:text-zinc-400 py-4">
                      <div className="flex items-center gap-2 p-1 pl-0 rounded-lg">
                        <div className="h-6 w-6 rounded-full bg-[#57715B]/10 flex items-center justify-center">
                          <UserIcon className="h-3 w-3 text-[#57715B]" />
                        </div>
                        <span className="font-medium">{movement.usuario_nome}</span>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
                {filteredMovements.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={8} className="h-64 text-center">
                      <div className="flex flex-col items-center justify-center gap-3 opacity-50">
                        <FileText className="h-12 w-12 text-[#57715B] dark:text-[#E6DCCF]" />
                        <p className="text-[#57715B] dark:text-[#E6DCCF] font-medium">Nenhuma movimentação encontrada</p>
                      </div>
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </div>

          {/* Pagination Bottom */}
          <div className="flex justify-center pb-8 opacity-60 hover:opacity-100 transition-opacity">
            <span className="text-xs font-medium text-[#57715B] dark:text-[#E6DCCF]">
              {productSearch
                ? `Mostrando ${filteredMovements.length} movimentações encontradas para "${productSearch}"`
                : `Mostrando ${filteredMovements.length} registros nesta página`
              }
            </span>
          </div>

        </div>
      </div>
    </PermissionBlur>
  );
}

