import { useState, useCallback, useRef, useEffect } from "react";
import { useMiaPageContext } from "@/features/mia/hooks/useMiaPageContext";
import { ArrowDownCircle, ArrowUpCircle, QrCode, Camera, Bluetooth, Loader2, Package, Trash2, AlertCircle, CheckCircle2, PackageOpen, History, Store } from "lucide-react";
import { Link } from "react-router-dom";
import { Button } from "@/shared/ui/button";
import { Badge } from "@/shared/ui/badge";
import { Card, CardContent } from "@/shared/ui/card";
import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/shared/ui/use-toast";
import { handleError } from '@/shared/lib/error-handler';
import { useStore } from "@/shared/contexts/StoreContext";
import { DashboardLayout } from "@/features/dashboard/ui/DashboardLayout";
import { clsx } from "clsx";
import {
    useEtiquetaScanner,
    playSuccessSound,
    playErrorSound,
    formatBipError,
    isDuplicateBipError,
    type ScannedPayload,
} from "@/shared/hooks/useEtiquetaScanner";
import { CameraScannerStatus } from "@/features/logistica/ui/CameraScannerStatus";
import { SaidaAvulsaDialog, type EtiquetaContext } from "@/features/logistica/ui/SaidaAvulsaDialog";
import { shouldSkipManualMovimentacao, type SaidaDestino } from "@/features/logistica/lib/expositora";

// Compatibilidade com o resto do componente — alias do tipo do hook
type ScannedData = ScannedPayload;

interface ProductInfo {
    id: number;
    nome: string;
    foto_url?: string;
}

interface ScannedItem {
    id: string;
    rawQr: string;
    data: ScannedData;
    productInfo?: ProductInfo;
    status: 'pending' | 'loading' | 'success' | 'error' | 'duplicate';
    error?: string;
    /** Status da etiqueta no banco — informativo, não bloqueia contagem */
    etiquetaStatus?: string;
    /** Snapshot da etiqueta do banco — usado pelo modal de saída avulsa */
    etiqueta?: {
        quantidade_interna: number;
        quantidade_disponivel: number;
        tipo_embalagem: string | null;
        embalagem_nome: string | null;
        lote_codigo: string | null;
    };
}

// Sons centralizados em useEtiquetaScanner — playSuccessSound/playErrorSound importados.

export function ScannerContent() {
    const { toast } = useToast();
    const { selectedStore } = useStore();

    const [scannedItems, setScannedItems] = useState<ScannedItem[]>([]);
    const [isProcessing, setIsProcessing] = useState(false);
    // Dedup local via ref pra evitar race condition (callback de setState
    // não é confiável pra ler estado síncrono em React 18 concurrent).
    const uidsLidosRef = useRef<Set<string>>(new Set());

    // Chave do localStorage por loja — filas de lojas diferentes não se misturam.
    const queueKey = selectedStore ? `scanner_queue_v1_${selectedStore.id}` : null;

    // Restore da fila ao montar (ou ao trocar de loja): itens 'loading' interrompidos
    // voltam como 'pending' já que o processamento não chegou a concluir.
    useEffect(() => {
        if (!queueKey) return;
        try {
            const raw = localStorage.getItem(queueKey);
            if (!raw) return;
            const saved: ScannedItem[] = JSON.parse(raw);
            const restored = saved.map(i =>
                i.status === 'loading' ? { ...i, status: 'pending' as const } : i
            );
            setScannedItems(restored);
            restored.forEach(i => { if (i.data.uid) uidsLidosRef.current.add(i.data.uid); });
        } catch { /* localStorage corrompido — ignora, começa limpo */ }
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [queueKey]);

    // Persiste a fila a cada mudança.
    useEffect(() => {
        if (!queueKey) return;
        try { localStorage.setItem(queueKey, JSON.stringify(scannedItems)); } catch { /* quota — ignora */ }

