import { usePermissions } from '@/shared/hooks/usePermissions';
import { useStore } from '@/shared/contexts/StoreContext';
import { useIsMobile } from '@/shared/hooks/use-mobile';
import { useLocation, useNavigate } from 'react-router-dom';
import { useTheme } from 'next-themes';

vi.mock('@/shared/hooks/useAuth', () => ({ useAuth: vi.fn() }));
vi.mock('@/shared/hooks/usePermissions', () => ({ usePermissions: vi.fn() }));
vi.mock('@/shared/contexts/StoreContext', () => ({ useStore: vi.fn() }));
vi.mock('@/shared/hooks/use-mobile', () => ({ useIsMobile: vi.fn() }));
vi.mock('react-router-dom', () => ({
  useLocation: vi.fn(),
  useNavigate: vi.fn(),
}));
vi.mock('next-themes', () => ({ useTheme: vi.fn() }));

vi.mock('@/shared/ui/DashboardStoreSelector', () => ({
  StoreSelector: () => <div data-testid="store-selector" />,
}));

// Config global variables that Vite defines
vi.stubGlobal('__APP_VERSION__', '1.0.0');
vi.stubGlobal(
  'fetch',
  vi.fn(() =>
    Promise.resolve({
      ok: true,
      json: () => Promise.resolve({ version: '1.0.0' }),
    }),
  ),
);

HTMLElement.prototype.scrollTo = vi.fn();

describe('MobileHome', () => {
  const mockNavigate = vi.fn();

  beforeEach(() => {
    vi.clearAllMocks();

    vi.mocked(useNavigate).mockReturnValue(mockNavigate);
    vi.mocked(useLocation).mockReturnValue({ search: '' } as any);
    vi.mocked(useIsMobile).mockReturnValue(true);

    vi.mocked(useTheme).mockReturnValue({
      theme: 'light',
      setTheme: vi.fn(),
    } as any);

    vi.mocked(useAuth).mockReturnValue({
      user: { user_metadata: { nome: 'Maria Silva' } },
      userProfile: { nome: 'Maria Silva' },
      signOut: vi.fn(),
    } as any);

    vi.mocked(useStore).mockReturnValue({
      selectedStore: { shortName: 'Loja Centro' },
    } as any);

    vi.mocked(usePermissions).mockReturnValue({
      isAdmin: false,
    } as any);
  });

  it('renders nothing if not on mobile', () => {
    vi.mocked(useIsMobile).mockReturnValue(false);
    const { container } = render(<MobileHome />);
    expect(container).toBeEmptyDOMElement();
  });

  it('renders mobile layout with greetings', () => {
    render(<MobileHome />);

    // Check for greeting insight roughly using substring matching
    const firstName = 'Maria';
    // Instead of testing a specific random pun, we check for elements surrounding it
    expect(screen.getByText('sistema GIDAPE')).toBeInTheDocument();

    // Store name
    expect(screen.getByText('Loja Centro')).toBeInTheDocument();

    // Check categories
    // Since UI displays the active category name prominently
    // `pageIndex` defaults to 'estoque' often
    expect(screen.getAllByText(/Estoque/i).length).toBeGreaterThan(0);
  });
});

